// RedactionMode is an enumeration type.
type RedactionMode string

const (
	// RedactionModeMask RedactionModeMask replace with the category's redaction template, e.g. `[EMAIL]`.
	//
	// The default, because it is the only mode that is both irreversible and needs no
	// configuration. A default of [`RedactionMode::Pseudonymize`] would mean the
	// out-of-the-box path depends on a secret the operator has not yet set.
	RedactionModeMask RedactionMode = "mask"
	// RedactionModeHash RedactionModeHash replace with a short blake3 digest of the original span.
	RedactionModeHash RedactionMode = "hash"
	// RedactionModePseudonymize RedactionModePseudonymize replace with a keyed, reversible token, e.g. `[EMAIL:k1:MZXW6YTB...]`.
	//
	// Equal values get equal tokens, so a reader can follow one pseudonymous person
	// through a corpus, and a holder of the key can reverse it. Requires a key: see
	// [`RedactionEngine::new`](crate::redaction::RedactionEngine::new).
	RedactionModePseudonymize RedactionMode = "pseudonymize"
	// RedactionModeRemove RedactionModeRemove delete the span entirely.
	RedactionModeRemove RedactionMode = "remove"
	// RedactionModeCustom RedactionModeCustom replace using [`RedactionConfig::custom_template`].
	RedactionModeCustom RedactionMode = "custom"
)


