	s.TargetDpi = raw.TargetDpi
	s.MaxImageDimension = raw.MaxImageDimension
	s.InjectPlaceholders = raw.InjectPlaceholders
	s.AutoAdjustDpi = raw.AutoAdjustDpi
	s.MinDpi = raw.MinDpi
	s.MaxDpi = raw.MaxDpi
	s.MaxImagesPerPage = raw.MaxImagesPerPage
	s.Classify = raw.Classify
	s.IncludePageRasters = raw.IncludePageRasters
	s.RunOcrOnImages = raw.RunOcrOnImages
	s.OcrTextOnly = raw.OcrTextOnly
	s.AppendOcrText = raw.AppendOcrText
	s.IncludeDataBase64 = raw.IncludeDataBase64
