// BuildEditorProjection alias with a descriptive name for callers that prefer the output type as the verb.
func BuildEditorProjection(document ExtractedDocument, options EditorProjectionOptions) (*EditorEnvelope, error) {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	jsonBytescDocument, err := json.Marshal(document)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescDocument) == "null" {
		jsonBytescDocument = []byte("{}")
	}
	tmpStrcDocument := C.CString(string(jsonBytescDocument))
	cDocument := C.hacienda_extracted_document_from_json(tmpStrcDocument)
	C.free(unsafe.Pointer(tmpStrcDocument))
	if cDocument == 0 {
		return nil, wrapLastError("failed to create extracted_document")
	}
	defer C.hacienda_extracted_document_free(cDocument)


	jsonBytescOptions, err := json.Marshal(options)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescOptions) == "null" {
		jsonBytescOptions = []byte("{}")
	}
	tmpStrcOptions := C.CString(string(jsonBytescOptions))
	cOptions := C.hacienda_editor_projection_options_from_json(tmpStrcOptions)
	C.free(unsafe.Pointer(tmpStrcOptions))
	if cOptions == 0 {
		return nil, wrapLastError("failed to create editor_projection_options")
	}
	defer C.hacienda_editor_projection_options_free(cOptions)


	ptr := C.hacienda_build_editor_projection(cDocument, cOptions)
	defer C.hacienda_editor_envelope_free(ptr)
	jsonPtr := C.hacienda_editor_envelope_to_json(ptr)
	if jsonPtr == nil {
		return nil, fmt.Errorf("failed to convert to JSON")
	}
	defer C.hacienda_free_string(jsonPtr)
	var result EditorEnvelope
	if err := json.Unmarshal([]byte(C.GoString(jsonPtr)), &result); err != nil {
		return nil, fmt.Errorf("failed to unmarshal: %w", err)
	}
	return &result, nil
}


