// Close shut down every store the facade holds: seal the audit segment and release the
// review store's resources.
//
// Calling `close` is recommended when the facade holds a [`FileAuditStore`]: it
// seals the open segment so the next process finds a clean chain with no unsealed
// orphan. If you skip `close`, recovery on the next open replays and seals the
// orphan automatically — so forgetting `close` loses no data. The difference is
// one extra recovery step on the next startup.
//
// `close` is idempotent: calling it more than once returns `Ok(())` on every
// subsequent call. When no stores are configured it is a no-op.
//
// # Why both stores are closed even if the first fails
//
// A failed audit seal must not leave a review store's resources held. Both closes
// are attempted and the first error is returned, so one broken backend cannot make
// the other leak.
//
// # Why not `Drop`
//
// `Drop` cannot `.await`. `block_on` inside `Drop` panics when called from within
// a Tokio runtime, and a detached `tokio::spawn` risks the process exiting before
// the write completes. Recovery is the correct backstop; `close` is the courtesy
// that avoids the extra startup work.
//
// # Multi-tenant caveat (S1b)
//
// Seals only `caller`'s own tenant's open segment — [`AuditStore::close`] takes a
// tenant and the store has no "every tenant that ever touched me" enumeration to
// close them all. A process serving several tenants that calls plain `close()`
// (which acts as [`TenantId::default_tenant()`] via `Caller::Trusted`) leaves every
// other tenant's segment unsealed at shutdown. That is not a data-loss gap — see
// the recovery note above — but it does mean a multi-tenant deployment that wants
// every chain sealed before exit must call `close_with_auth` once per tenant it has
// actually served, not just once. Tracked as a follow-up to close alongside this
// gap rather than solved here.
//
// Errors are returned when returns [`HaciendaError::Audit`] if the seal write fails, or
// [`HaciendaError::Review`] if the review store's cleanup fails.
//
// [`FileAuditStore`]: crate::audit::FileAuditStore
func (h *HaciendaFacade) Close() error {
	return h.CloseWithContext(context.Background())
}

// CloseWithContext is Close with a context: when ctx ends, the in-flight native
// request is aborted and the returned error wraps ctx.Err().
func (h *HaciendaFacade) CloseWithContext(ctx context.Context) error {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	if err := ctx.Err(); err != nil {
		return err
	}
	cancelToken := C.hacienda_cancel_token_new()
	if cancelToken == 0 {
		if err := lastError(); err != nil {
			return err
		}
		return fmt.Errorf("failed to create cancel token")
	}
	cancelDone := make(chan struct{})
	cancelStopped := make(chan struct{})
	go func() {
		defer close(cancelStopped)
		select {
			case <-ctx.Done():
			C.hacienda_cancel_token_cancel(cancelToken)
			case <-cancelDone:
		}
	}()
	defer func() {
		close(cancelDone)
		<-cancelStopped
		C.hacienda_cancel_token_free(cancelToken)
	}()
	C.hacienda_hacienda_facade_close_cancellable(h.ptr, cancelToken)
	return lastErrorContext(ctx)
}


