// Apply overlay command-line values. Absent overrides leave the field untouched.
//
// Supplying `model_dir` also enables the model: naming a model and then
// silently not running it is never what the caller meant.
func (r *PipelineConfig) Apply(overrides CliOverrides) error {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	jsonBytescOverrides, err := json.Marshal(overrides)
	if err != nil {
		return fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescOverrides) == "null" {
		jsonBytescOverrides = []byte("{}")
	}
	tmpStrcOverrides := C.CString(string(jsonBytescOverrides))
	cOverrides := C.hacienda_cli_overrides_from_json(tmpStrcOverrides)
	C.free(unsafe.Pointer(tmpStrcOverrides))
	if cOverrides == 0 {
		return wrapLastError("failed to create cli_overrides")
	}
	defer C.hacienda_cli_overrides_free(cOverrides)


	jsonBytesRecv, err := json.Marshal(r)
	if err != nil {
		return fmt.Errorf("failed to marshal receiver: %w", err)
	}
	tmpStrRecv := C.CString(string(jsonBytesRecv))
	cRecv := C.hacienda_pipeline_config_from_json(tmpStrRecv)
	C.free(unsafe.Pointer(tmpStrRecv))
	if cRecv == 0 {
		return wrapLastError("failed to create receiver")
	}
	defer C.hacienda_pipeline_config_free(cRecv)
	C.hacienda_pipeline_config_apply(cRecv, cOverrides)
	jsonPtrUpdated := C.hacienda_pipeline_config_to_json(cRecv)
	if jsonPtrUpdated != nil {
		_ = json.Unmarshal([]byte(C.GoString(jsonPtrUpdated)), r)
		C.hacienda_free_string(jsonPtrUpdated)
	}
	return nil
}


