// entry is replaced with a freshly resolved one. That is the path a key rotation
// takes (see P3): re-admit the tenant after the resolver reports a new active key.
//
// Errors are returned when whatever `resolver` returns for a missing or malformed key — see
// [`Pseudonymiser::new`] / [`Pseudonymiser::with_active`].
func (h *TenantPseudonymiserRegistry) Admit(tenant *TenantID, resolver KeyResolver, active *KeyID, retired []KeyID) error {
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()
	cTenant := tenant.ptr


	jsonBytescResolver, err := json.Marshal(resolver)
	if err != nil {
		return fmt.Errorf("failed to marshal: %w", err)
	}
	// When the parameter is a nil pointer (Option<&T> on the Rust side), json.Marshal
	// emits "null" which the FFI's _from_json rejects. Substitute "{}" so a default
	// instance is constructed instead — semantically equivalent to None for query types
	// whose fields are all optional with serde(default).
	if string(jsonBytescResolver) == "null" {
		jsonBytescResolver = []byte("{}")
	}
	tmpStrcResolver := C.CString(string(jsonBytescResolver))
	cResolver := C.hacienda_key_resolver_from_json(tmpStrcResolver)
	C.free(unsafe.Pointer(tmpStrcResolver))
	if cResolver == 0 {
		return wrapLastError("failed to create key_resolver")
	}
	defer C.hacienda_key_resolver_free(cResolver)


	cActive := active.ptr


	jsonBytescRetired, err := json.Marshal(retired)
	if err != nil {
		return fmt.Errorf("failed to marshal: %w", err)
	}
	// A nil Go slice or map marshals to "null", while a non-nil empty one marshals to
	// "[]" — the form serde_json writes for an empty Rust collection, and the only
	// one the FFI's from_str accepts. Normalise so both spellings of "empty" cross the ABI
	// identically.
	if string(jsonBytescRetired) == "null" {
		jsonBytescRetired = []byte("[]")
	}
	cRetired := C.CString(string(jsonBytescRetired))
	defer C.free(unsafe.Pointer(cRetired))


	C.hacienda_tenant_pseudonymiser_registry_admit(h.ptr, cTenant, cResolver, cActive, cRetired)
	return lastError()
}


